import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { downloadLicence } from "../src/download-licences.js";
import worker from "../src/worker.js";

const DATE = "2026-11-20";
const STM = "/v2/stm/download";
const OC = "/v2/octranspo/download";
const TABLES = [
  "stop_events", "trip_days", "scheduled_stop_times", "vehicle_positions",
  "alerts", "feed_polls", "prediction_samples",
];
const SHA = "1".repeat(64);

test("published download licences match the approved JSON byte for byte", () => {
  // Generated by downloadLicence on main at 99e88f03, before declaration-driven licensing.
  const golden = JSON.parse(readFileSync(
    new URL("./fixtures/download-licences.golden.json", import.meta.url), "utf8",
  ));
  for (const [city, source] of [
    ["stm", { en: "STM", fr: "de la STM" }],
    ["octranspo", { en: "OC Transpo", fr: "d’OC Transpo" }],
  ]) {
    const expected = golden.licences[city];
    const { checked_on, non_endorsement, name, attribution, url, limits } = expected;
    const input = {
      labels: { en: { operator: source.en }, fr: { operator: source.en } },
      download_licence: { checked_on, name, attribution, url, limits, non_endorsement, source },
    };
    assert.equal(JSON.stringify(downloadLicence(input, golden.date)), JSON.stringify(expected), city);
  }
});

function provider(id, operator, alerts = true, licensed = true) {
  const bilingual = (value) => ({ en: value, fr: value });
  return {
    id,
    timezone: "America/Toronto",
    labels: { en: { operator }, fr: { operator } },
    inputs: { i3_alerts: alerts, service_alerts: false },
    download_licence: licensed ? {
      checked_on: "2026-11-22",
      name: bilingual("Fixture licence"),
      attribution: bilingual(`Contains information licensed under ${operator}'s terms.`),
      url: bilingual("https://licence.example.org/terms"),
      limits: bilingual("Provided as is."),
      non_endorsement: bilingual("Transit is independent."),
      source: { en: operator, fr: `de l’organisme ${operator}` },
    } : null,
  };
}

function fixture(t, { city = "stm", status, missing = false, admitted = true, alerts = true,
  endpoint = "fixture.r2.cloudflarestorage.com", r2Error, wrongRange = false, version = "11" } = {}) {
  const tables = ["12", "13"].includes(version) ? [...TABLES, "segment_runs"] : TABLES;
  const manifest = {
    provider: city,
    service_date: DATE,
    cleaning_version: version,
    ...(status ? { status } : {
      ...(alerts ? {} : { alerts: "not_tracked" }),
      files: Object.fromEntries(tables.filter((name) => alerts || name !== "alerts").map(
        (name) => [`${name}.parquet`, { sha256: SHA, byte_size: 5 }],
      )),
    }),
  };
  const keys = [];
  const methods = [];
  const requests = [];
  const admissions = [];
  const upstream = [];
  const env = {
    TRANSIT1_ENGINE_ACCESS_TOKEN: "test",
    TRANSIT1_R2_ENDPOINT: endpoint,
    TRANSIT1_R2_READ_ACCESS_KEY_ID: "fixture-key",
    TRANSIT1_R2_READ_SECRET_ACCESS_KEY: "fixture-secret",
    QUESTION_LIMIT: {
      async limit({ key }) {
        admissions.push(key);
        return { success: admitted };
      },
    },
    ENGINE: {
      async fetch(request) {
        const url = new URL(request.url);
        upstream.push(url);
        if (url.pathname === "/cities") {
          return Response.json({
            default_provider: "stm",
            providers: [
              provider("stm", "STM"),
              provider("octranspo", "OC Transpo", false),
              provider("new_city", "Example Transit"),
              provider("unlicensed", "Example Agency", true, false),
            ],
          });
        }
        assert.equal(url.pathname, "/data-health");
        return Response.json({}, { headers: { "x-transit-cleaning-version": version } });
      },
    },
  };
  t.mock.method(globalThis, "fetch", async (input, init) => {
    // Workers rejects this redirect mode before sending a subrequest. Node accepts it.
    if (init?.redirect === "error") throw new TypeError("Unsupported redirect mode");
    const request = new Request(input, init);
    const url = new URL(request.url);
    assert.equal(url.origin, "https://fixture.r2.cloudflarestorage.com");
    assert.ok(url.pathname.startsWith("/transit-clean/"));
    assert.equal(request.redirect, "manual");
    assert.match(request.headers.get("authorization"),
      /^AWS4-HMAC-SHA256 Credential=fixture-key\/\d{8}\/auto\/s3\/aws4_request, /);
    assert.ok(["GET", "HEAD"].includes(request.method));

    const key = url.pathname.slice("/transit-clean/".length);
    keys.push(key);
    methods.push(request.method);
    requests.push(request);
    if (r2Error) return new Response(null, {
      status: r2Error,
      headers: r2Error === 302 ? { location: "https://redirect.test/" } : undefined,
    });
    if (key.endsWith("/manifest.json")) {
      assert.equal(request.method, "GET");
      if (missing || key !== `${city}/${DATE}/v${version}/manifest.json`) {
        return new Response(null, { status: 404 });
      }
      const body = JSON.stringify(manifest);
      return new Response(body, { headers: { "content-length": String(Buffer.byteLength(body)) } });
    }
    assert.ok(tables.some((table) => key === `${city}/${DATE}/v${version}/${table}.parquet`));
    const body = "PAR1!";
    const range = request.headers.get("range");
    if (!range) return new Response(request.method === "HEAD" ? null : body, {
      headers: { "content-length": String(body.length) },
    });
    const [start, end] = range.slice("bytes=".length).split("-").map(Number);
    return new Response(body.slice(start, end + 1), {
      status: 206,
      headers: {
        "content-length": String(end - start + 1),
        "content-range": `bytes ${wrongRange ? start + 1 : start}-${end}/${body.length}`,
      },
    });
  });
  const fetch = (path, init) => worker.fetch(new Request("https://data.test" + path, init), env, {
    waitUntil(promise) { return promise; },
  });
  return { fetch, admissions, keys, methods, requests, upstream };
}

test("a dated listing uses the public city catalog, current version and manifest identities", async (t) => {
  const { fetch, keys, upstream, admissions } = fixture(t);
  const response = await fetch(STM + "?date=" + DATE);
  assert.equal(response.status, 200);
  assert.equal(response.headers.get("cache-control"), "no-store");
  const day = await response.json();
  assert.equal(day.cleaning_version, "11");
  assert.equal(day.status, "complete");
  assert.equal(day.files.length, 7);
  assert.deepEqual(day.files[0], {
    name: "stop_events.parquet", byte_size: 5, sha256: SHA,
    url: `${STM}/${DATE}/stop_events.parquet?version=11`,
  });
  assert.equal(upstream[1].searchParams.get("from"), DATE);
  assert.deepEqual(keys, [`stm/${DATE}/v11/manifest.json`]);
  assert.equal(admissions.length, 1);
  const readme = await fetch(day.readme_url);
  assert.match(readme.headers.get("content-type"), /^text\/plain/);
  assert.match(readme.headers.get("content-disposition"), /README\.txt/);
  const text = await readme.text();
  for (const lang of ["en", "fr"]) {
    assert.ok(text.includes(day.licence.attribution[lang]));
    assert.ok(text.includes(day.licence.changes[lang]));
    assert.ok(text.includes(day.licence.url[lang]));
  }
  assert.ok(text.includes(SHA));
});

for (const version of ["12", "13"]) {
  test(`v${version} lists and serves the segment runs file`, async (t) => {
    const { fetch } = fixture(t, { version });
    const response = await fetch(STM + "?date=" + DATE);
    assert.equal(response.status, 200);
    const listing = await response.json();
    const url = `${STM}/${DATE}/segment_runs.parquet?version=${version}`;
    assert.deepEqual(listing.files.find(({ name }) => name === "segment_runs.parquet"), {
      name: "segment_runs.parquet", byte_size: 5, sha256: SHA, url,
    });
    const file = await fetch(url);
    assert.equal(file.status, 200);
    assert.equal(await file.text(), "PAR1!");
  });
}

test("paths, service dates, versions and nonpublic cities are refused before opening a file", async (t) => {
  const { fetch, keys } = fixture(t);
  for (const path of [
    `${STM}/${DATE}/%2e%2e%2fstop_events.parquet`,
    `${STM}/2026-02-30/stop_events.parquet`,
    `${STM}/${DATE}/other.parquet`,
    `/v2/sto/download/${DATE}/stop_events.parquet`,
    `${STM}/${DATE}/stop_events.parquet?version=10`,
  ]) {
    assert.equal((await fetch(path)).status, 404, path);
  }
  assert.equal((await fetch(`${STM}?date=${DATE}&date=${DATE}`)).status, 400);
  assert.equal((await fetch(STM, { method: "PUT" })).status, 405);
  assert.deepEqual(keys, []);
});

test("a missing day and a published unmeasured day have distinct states and no file links", async (t) => {
  for (const [settings, status, reason] of [
    [{ missing: true }, "missing", "no_manifest"],
    [{ status: "no_raw_captures" }, "not_measured", "no_raw_captures"],
    [{ status: "no_schedule_edition" }, "not_measured", "no_schedule_edition"],
    [{ status: "schedule_archive_unreadable" }, "not_measured", "schedule_archive_unreadable"],
  ]) {
    const { fetch, keys } = fixture(t, settings);
    const day = await (await fetch(STM + "?date=" + DATE)).json();
    assert.deepEqual([day.status, day.reason, day.files, day.readme_url], [status, reason, [], null]);
    assert.equal((await fetch(`${STM}/${DATE}/stop_events.parquet`)).status, 404);
    assert.equal((await fetch(`${STM}/${DATE}/README.txt`)).status, 404);
    assert.ok(keys.every((key) => key.endsWith("/manifest.json")));
  }
});

test("Ottawa without tracked alerts has its own licence and no alerts download", async (t) => {
  const { fetch } = fixture(t, { city: "octranspo", alerts: false });
  const day = await (await fetch(OC + "?date=" + DATE)).json();
  assert.equal(day.alerts_not_tracked, true);
  assert.equal(day.files.length, 6);
  assert.match(day.licence.attribution.en, /^Contains information licensed under/);
  assert.match(day.licence.changes.en, /OC Transpo/);
  assert.equal((await fetch(`${OC}/${DATE}/alerts.parquet`)).status, 404);
});

test("downloads follow the public declaration licence for any city", async (t) => {
  const { fetch, keys } = fixture(t, { city: "new_city" });
  assert.equal((await fetch("/v2/unlicensed/download?date=" + DATE)).status, 404);
  assert.deepEqual(keys, []);
  const response = await fetch("/v2/new_city/download?date=" + DATE);
  assert.equal(response.status, 200);
  const day = await response.json();
  assert.match(day.licence.changes.en, /Example Transit/);
  assert.equal(day.licence.url.fr, "https://licence.example.org/terms");
});

test("download streams Parquet with attachment, SHA-256 ETag, HEAD and byte ranges", async (t) => {
  const { fetch, methods } = fixture(t);
  const path = `${STM}/${DATE}/stop_events.parquet`;
  const response = await fetch(path);
  assert.equal(response.status, 200);
  assert.equal(response.headers.get("content-type"), "application/vnd.apache.parquet");
  assert.equal(response.headers.get("content-disposition"), `attachment; filename="transit-stm-${DATE}-v11-stop_events.parquet"`);
  assert.equal(response.headers.get("content-length"), "5");
  assert.equal(response.headers.get("accept-ranges"), "bytes");
  assert.equal(response.headers.get("etag"), `"${SHA}"`);
  assert.equal(response.headers.get("cache-control"), "no-store");
  assert.equal(response.headers.get("access-control-allow-origin"), "*");
  assert.equal(await response.text(), "PAR1!");

  const head = await fetch(path, { method: "HEAD" });
  assert.equal(methods.at(-1), "HEAD");
  assert.equal(head.headers.get("content-length"), "5");
  assert.equal(head.body, null);
  assert.equal((await fetch(path, { headers: { "if-none-match": `W/"${SHA}"` } })).status, 304);

  const partial = await fetch(path, { headers: { range: "bytes=1-2" } });
  assert.equal(partial.status, 206);
  assert.equal(partial.headers.get("content-range"), "bytes 1-2/5");
  assert.equal(await partial.text(), "AR");
  assert.equal((await fetch(path, { headers: { range: "bytes=5-" } })).headers.get("content-range"), "bytes */5");
  assert.equal((await fetch(path, { headers: { range: "bytes=1-2", "if-range": '"old"' } })).status, 200);
});

test("listing admission applies before catalog and bucket work", async (t) => {
  const { fetch, keys, upstream, admissions } = fixture(t, { admitted: false });
  const response = await fetch(STM + "?date=" + DATE, { headers: { "cf-connecting-ip": "192.0.2.1" } });
  assert.equal(response.status, 503);
  assert.equal(response.headers.get("retry-after"), "60");
  assert.equal(admissions.length, 1);
  assert.deepEqual([keys, upstream], [[], []]);
});

test("closed-day metadata uses the versioned cache while every listing is admitted", async (t) => {
  const entries = new Map();
  const previous = Object.getOwnPropertyDescriptor(globalThis, "caches");
  Object.defineProperty(globalThis, "caches", {
    configurable: true,
    value: { default: {
      async match(key) { return entries.get(key.url)?.clone(); },
      async put(key, response) { entries.set(key.url, response); },
    } },
  });
  t.after(() => {
    if (previous) Object.defineProperty(globalThis, "caches", previous);
    else delete globalThis.caches;
  });
  const { fetch, keys, upstream, admissions } = fixture(t);
  for (let index = 0; index < 2; index++) {
    assert.equal((await fetch(STM + "?date=" + DATE)).status, 200);
  }
  assert.equal(keys.length, 1);
  assert.equal(upstream.length, 2);
  assert.equal(admissions.length, 2);
  const version = "https://data.test/__transit_download_cache/v2/version";
  const day = `https://data.test/__transit_download_cache/v2/stm/${DATE}/v11`;
  assert.equal(entries.get(version).headers.get("cache-control"), "public, max-age=30");
  assert.equal(entries.get(day).headers.get("cache-control"), "public, max-age=604800");
  entries.set(version, new Response("12"));
  const nextDay = await (await fetch(STM + "?date=" + DATE)).json();
  assert.equal(nextDay.status, "missing");
  assert.deepEqual(keys, [`stm/${DATE}/v11/manifest.json`, `stm/${DATE}/v12/manifest.json`]);
});

test("signed storage fails closed on invalid endpoints, refused credentials and wrong ranges", async (t) => {
  const invalid = fixture(t, { endpoint: "https://fixture.r2.cloudflarestorage.com@example.test" });
  assert.equal((await invalid.fetch(STM + "?date=" + DATE)).status, 503);
  assert.deepEqual(invalid.keys, []);

  const denied = fixture(t, { r2Error: 403 });
  const deniedResponse = await denied.fetch(STM + "?date=" + DATE);
  assert.equal(deniedResponse.status, 503);
  assert.deepEqual(await deniedResponse.json(), { message: "downloads unavailable" });
  assert.equal(denied.keys.length, 1);

  const wrong = fixture(t, { wrongRange: true });
  const ranged = await wrong.fetch(`${STM}/${DATE}/stop_events.parquet`, {
    headers: { range: "bytes=1-2" },
  });
  assert.equal(ranged.status, 503);
});

test("the Worker refuses R2 redirects without forwarding signed headers", async (t) => {
  const { fetch, keys } = fixture(t, { r2Error: 302 });
  const response = await fetch(STM + "?date=" + DATE);
  assert.equal(response.status, 503);
  assert.deepEqual(keys, [`stm/${DATE}/v11/manifest.json`]);
});

test("a ranged R2 read matches the fixed SigV4 signature", async (t) => {
  t.mock.timers.enable({ apis: ["Date"], now: new Date("2026-11-20T12:34:56Z") });
  const { fetch, requests } = fixture(t);
  const response = await fetch(`${STM}/${DATE}/stop_events.parquet`, {
    headers: { range: "bytes=1-2" },
  });
  assert.equal(response.status, 206);
  const signed = requests.at(-1);
  assert.equal(signed.headers.get("x-amz-date"), "20261120T123456Z");
  // Cross-checked against aws4fetch 1.0.20 with this fixed request and fixture credentials.
  assert.equal(signed.headers.get("authorization"),
    "AWS4-HMAC-SHA256 Credential=fixture-key/20261120/auto/s3/aws4_request, " +
    "SignedHeaders=host;range;x-amz-content-sha256;x-amz-date, " +
    "Signature=b114114ecf208c15a970e29ddeb1197699d794f64496da64ce6a05823c65ee12");
});
